/**
 * Template Field Manifests for da3watfarah.com
 *
 * Generated by scanning every `data-bind="X"` attribute (and its
 * data-bind-default value) across all 18 VIP template HTML files under
 * vip/. Loaded
 * synchronously (plain <script>, no network round trip) by
 * create-invitation.html so the wizard can show/hide fields based on
 * what the currently-selected template actually renders.
 *
 * Regenerate by re-running the scan below whenever a VIP template's
 * data-bind attributes change (path pattern: vip/CATEGORY/DEMO/FILE.html):
 *   grep -o 'data-bind="[^"]*"' vip/CATEGORY/DEMO/FILE.html
 *
 * All 18 VIP templates collapse into 3 field groups (every template in
 * a group binds the exact same key set):
 *   - "couple"  : two-person events (wedding/engagement) -> coupleNames,
 *                 groomFamily, brideFamily
 *   - "single"  : one-person events (birthday/newborn/graduation/ramadan)
 *                 -> personName (+ ageSentence for birthday templates)
 *   - "henna"   : the henna-night template binds brideName directly
 *                 (no groom side at all)
 * Every group also supports: eventDateDisplay, eventDateTime,
 * googleMapsUrl, invitationId, invitationText, ogDescription, ogImage,
 * ogUrl, pageTitle, rsvpAction, venueAddress, venueName, plus
 * design.coverImage / design.galleryImages / design.musicUrl (all 18
 * templates use all three media fields).
 */
(function (global) {
    'use strict';

    var COMMON_FIELDS = [
        'eventDateDisplay', 'eventDateTime', 'googleMapsUrl', 'invitationText',
        'venueAddress', 'venueName'
    ];
    var MEDIA_FIELDS = ['coverImage', 'galleryImages', 'musicUrl'];

    var FIELD_GROUPS = {
        couple: {
            fields: COMMON_FIELDS.concat(['coupleNames', 'groomFamily', 'brideFamily']),
            // step3 (content/design) optional fields this group has no data-bind for at all
            unusedStep3Fields: ['welcomeText', 'loveStory', 'religiousVerse', 'colors']
        },
        single: {
            fields: COMMON_FIELDS.concat(['personName']),
            unusedStep3Fields: ['welcomeText', 'loveStory', 'religiousVerse', 'colors']
        },
        singleWithAge: {
            fields: COMMON_FIELDS.concat(['personName', 'ageSentence']),
            unusedStep3Fields: ['welcomeText', 'loveStory', 'religiousVerse', 'colors']
        },
        henna: {
            fields: COMMON_FIELDS.concat(['brideName']),
            unusedStep3Fields: ['welcomeText', 'loveStory', 'religiousVerse', 'colors']
        }
    };

    // templateId (matches TEMPLATES_CONFIG[].id / VipTemplateRenderer.VIP_TEMPLATE_MAP keys) -> group
    var TEMPLATE_GROUP = {
        'vip-editorial-noir': 'couple',
        'vip-garden-blush': 'couple',
        'vip-gate-of-joy': 'couple',
        'vip-grand-hall': 'couple',
        'vip-royal-maroon': 'couple',
        'vip-the-doves': 'couple',
        'vip-wax-seal': 'couple',
        'vip-white-hall': 'couple',
        'vip-starry-night': 'couple',
        'vip-the-ring': 'couple',
        'vip-henna-night': 'henna',
        'vip-castle-magic': 'singleWithAge',
        'vip-neon-glow': 'singleWithAge',
        'vip-clouds': 'single',
        'vip-rosebud': 'single',
        'vip-graduation': 'single',
        'vip-moon-stars': 'single'
    };

    // Static fallback Arabic/English label dictionary — always available even if
    // an AI-generated label call fails or is unreachable.
    var FIELD_LABELS = {
        personName: { ar: 'اسم صاحب/ة المناسبة', en: "Person's Name" },
        coupleNames: { ar: 'اسم العروسين', en: 'Couple Names' },
        brideName: { ar: 'اسم العروس', en: "Bride's Name" },
        groomFamily: { ar: 'عائلة العريس', en: "Groom's Family" },
        brideFamily: { ar: 'عائلة العروس', en: "Bride's Family" },
        eventDateDisplay: { ar: 'تاريخ المناسبة', en: 'Event Date' },
        eventDateTime: { ar: 'موعد المناسبة (تاريخ ووقت)', en: 'Event Date & Time' },
        venueName: { ar: 'اسم القاعة/المكان', en: 'Venue Name' },
        venueAddress: { ar: 'عنوان القاعة', en: 'Venue Address' },
        googleMapsUrl: { ar: 'رابط خرائط جوجل', en: 'Google Maps Link' },
        invitationText: { ar: 'نص الدعوة', en: 'Invitation Text' },
        ageSentence: { ar: 'جملة العمر', en: 'Age Sentence' },
        welcomeText: { ar: 'نص الترحيب', en: 'Welcome Text' },
        loveStory: { ar: 'قصة الحب', en: 'Love Story' },
        rsvpAction: { ar: 'رابط تأكيد الحضور', en: 'RSVP Link' },
        invitationId: { ar: 'معرّف الدعوة', en: 'Invitation ID' },
        monogram: { ar: 'شعار الأحرف الأولى', en: 'Monogram' },
        pageTitle: { ar: 'عنوان الصفحة', en: 'Page Title' },
        ogDescription: { ar: 'وصف المشاركة (Open Graph)', en: 'Share Description' },
        ogImage: { ar: 'صورة المشاركة (Open Graph)', en: 'Share Image' },
        ogUrl: { ar: 'رابط المشاركة', en: 'Share URL' },
        coverImage: { ar: 'صورة الغلاف', en: 'Cover Image' },
        galleryImages: { ar: 'صور المعرض', en: 'Gallery Images' },
        musicUrl: { ar: 'موسيقى الخلفية', en: 'Background Music' },
        colors: { ar: 'الألوان', en: 'Colors' },
        religiousVerse: { ar: 'الآية الدينية', en: 'Religious Verse' }
    };

    function getManifest(templateId) {
        var group = TEMPLATE_GROUP[templateId];
        if (!group) return null;
        var groupDef = FIELD_GROUPS[group];
        return {
            templateId: templateId,
            group: group,
            fields: groupDef.fields.concat(MEDIA_FIELDS),
            unusedStep3Fields: groupDef.unusedStep3Fields
        };
    }

    global.TemplateFieldManifests = {
        FIELD_GROUPS: FIELD_GROUPS,
        TEMPLATE_GROUP: TEMPLATE_GROUP,
        FIELD_LABELS: FIELD_LABELS,
        getManifest: getManifest
    };
})(window);
